function [r] = qnorm(q)
%QNORM  q made unit; a zero quaternion becomes the identity.
%   q: real[1][4] (passed a plain number)
%   returns r: real[1][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = zeros(4, 1);
    n = asils.pc.sqrt_(((((q(1) * q(1)) + (q(2) * q(2))) + (q(3) * q(3))) + (q(4) * q(4))));
    if (n < 1e-30)
        r = [0; 0; 0; 1];
    else
        r = [(q(1) / n); (q(2) / n); (q(3) / n); (q(4) / n)];
    end
end
